text.main.ts:
// project iniitialization
tiles.setCurrentTilemap(tilemap`level`)

// sprite set up
let player = sprites.create(assets.image`playerImage`, SpriteKind.Player)
tiles.placeOnTile(player, tiles.getTileLocation(10, 8))
controller.moveSprite(player)
scene.cameraFollowSprite(player)
player.z = 5

let enemy = sprites.create(assets.image`enemyImage`, SpriteKind.Enemy)
tiles.placeOnRandomTile(enemy, assets.tile`pathTile`)
enemy.follow(player, randint(30, 80))

let coinSprite = sprites.create(assets.image`coinImage`, SpriteKind.Food)
tiles.placeOnRandomTile(coinSprite, assets.tile`pathTile`)

// project events
sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite: Sprite, otherSprite: Sprite) {
    game.setGameOverEffect(false, effects.melt)
    game.gameOver(false)
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Food, function (sprite: Sprite, otherSprite: Sprite) {
    game.setGameOverEffect(true, effects.smiles)
    game.gameOver(true)
})
